/**
 * Test data for valid URLs
 */
export const VALID_URLS = [
  'https://example.com',
  'https://example.com/path',
  'https://example.com/path?query=value',
  'https://example.com/path#fragment',
  'https://subdomain.example.com',
  'https://example.com:8080',
  'http://localhost:3000',
  'http://127.0.0.1:8080',
