 */
export const DANGEROUS_URLS = [
  'javascript:alert(1)',
  'data:text/html,<script>alert(1)</script>',
  'vbscript:msgbox',
  'file:///etc/passwd',
  'JavaScript:alert(1)',
  'DATA:text/html,<script>alert(1)</script>',
  'VBSCRIPT:msgbox',
